JSONGenerator gen = JSON.createGenerator(false);
gen.writeStartObject();
gen.writeStringField('name', 'Acme');
gen.writeNumberField('n', 7);
gen.writeBooleanField('ok', true);
gen.writeNullField('missing');
gen.writeFieldName('items');
gen.writeStartArray();
gen.writeString('x');
gen.writeNumber(2);
gen.writeBoolean(false);
gen.writeNull();
gen.writeEndArray();
gen.writeEndObject();
System.assertEquals('{"name":"Acme","n":7,"ok":true,"missing":null,"items":["x",2,false,null]}', gen.getAsString());
System.assert(gen.isClosed());
JSONGenerator pretty = JSON.createGenerator(true);
pretty.writeStartObject();
pretty.writeStringField('name', 'Acme');
pretty.writeBooleanField('ok', true);
pretty.writeEndObject();
String prettyText = pretty.getAsString();
System.assert(prettyText.contains('  "name": "Acme"'));

